// Writes the kana data into components/kakijun/index.js as two generated blocks (do not edit them by hand).
//   node tools/kana-embed.mjs            regenerate both blocks
//   node tools/kana-embed.mjs --check    both blocks equal what the data files give
//
// kakijun-data (MIT, ours): data/kana/kana.json made compact, one character per line:
//   "あ":[count,[[end,len],…]]  or, for small kana, "ぁ":[count,[[end,len],…],{"yoko":[…],"tate":[…]}]  (place)
//   len = the length of the stroke's inked centreline (0–100 units, rounded), so that the part knows each stroke's
//   duration before it draws anything. Notes, sources, base and loop stay in kana.json.
// OFL-1.1 data (SIL OFL 1.1): data/kana/strokes.ofl.json, the stroke shapes derived from strokesvg (Klee One). Studio
//   inlines only a part's index.js (kit/core/build-core.mjs) and an Egatari file records only its sha256, so a part cannot
//   carry a separate data file today: the file is embedded verbatim (same keys, same values; its "_license" object first)
//   between the markers /* BEGIN OFL-1.1 data … */ and /* END OFL-1.1 data */ (only the JSON between them). OFL.txt, LICENSE-strokesvg.txt and strokes-CHANGES.md are copied
//   into components/kakijun/ next to it.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { inkLine, length } from './kana-svgpath.mjs';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
export const JS = path.join(ROOT, 'components', 'kakijun', 'index.js');
const DATA = path.join(ROOT, 'data', 'kana');
export const LICENSE_FILES = ['OFL.txt', 'LICENSE-strokesvg.txt', 'strokes-CHANGES.md'];

const DATA_BEGIN = '// ---- BEGIN kakijun-data (MIT; generated by tools/kana-embed.mjs from data/kana/kana.json; do not edit) ----';
const DATA_END = '// ---- END kakijun-data ----';
// The OFL data: exactly the JSON between the two markers (nothing else, so a reader can cut it out by the markers alone)
const OFL_BEGIN = '/* BEGIN OFL-1.1 data: kana stroke shapes derived from strokesvg (Klee One), SIL Open Font License 1.1, NOT under the MIT\n'
  + '   License of the code around it; see OFL.txt, LICENSE-strokesvg.txt and strokes-CHANGES.md in this folder, and "_license" below.\n'
  + '   Generated by tools/kana-embed.mjs from data/kana/strokes.ofl.json; do not edit. */';
const OFL_END = '/* END OFL-1.1 data */';
export const OFL_MARKERS = { begin: '/* BEGIN OFL-1.1 data', end: OFL_END };
// The OFL part as it sits in index.js: var STROKES = <begin> JSON <end>;
const OFL_PRE = 'var STROKES = ';

export const inkLength = (pieces) => Math.round(length(inkLine(pieces)));
export function compact(c, shapes) {
  const s = c.strokes.map((x, i) => [x.end, inkLength(shapes[i])]);
  return c.place ? [c.count, s, c.place] : [c.count, s];
}
export function dataBlock(data, ofl) {
  const lines = Object.entries(data.chars).map(([ch, c]) => JSON.stringify(ch) + ':' + JSON.stringify(compact(c, ofl.chars[ch])));
  return [DATA_BEGIN, `// ${Object.keys(data.chars).length} characters, data version ${data.version} (order, endings, small-kana placement: original, MIT)`,
    'var KANA = {', lines.join(',\n'), '};', DATA_END].join('\n');
}
// The OFL file as JSON: the same keys and values, "_license" first, one character per line
export function shapesJson(ofl) {
  const keys = ['_license', ...Object.keys(ofl).filter((k) => k !== '_license' && k !== 'chars')];
  const head = keys.map((k) => JSON.stringify(k) + ': ' + JSON.stringify(ofl[k])).join(',\n');
  const chars = Object.entries(ofl.chars).map(([ch, v]) => JSON.stringify(ch) + ': ' + JSON.stringify(v)).join(',\n');
  return '{' + head + ',\n"chars": {\n' + chars + '\n}}';
}
export const stringsBlock = (ofl) => OFL_PRE + OFL_BEGIN + '\n' + shapesJson(ofl) + '\n' + OFL_END + ';';
// The text between the two markers (for the test: it must be the shapes JSON and nothing else)
export function between2(src) {
  const i = src.indexOf(OFL_MARKERS.begin), j = src.indexOf(OFL_END);
  if (i < 0 || j < i || src.indexOf(OFL_MARKERS.begin, i + 1) >= 0 || src.indexOf(OFL_END, j + 1) >= 0) return null;
  return src.slice(src.indexOf('*/', i) + 2, j);
}
const between = (src, a, b) => {
  const i = src.indexOf(a), j = src.indexOf(b);
  if (i < 0 || j < i) throw new Error(`${path.relative(ROOT, JS)}: no block ${a.slice(0, 40)}…`);
  return [i, j + b.length];
};
const objOf = (block, name) => JSON.parse(block.split('\n').filter((l) => !l.startsWith('//')).join('\n').replace(new RegExp(`^var ${name} = `), '').replace(/;\s*$/, ''));
// What index.js carries (for tools/test-kakijun.mjs)
export function readEmbedded(src = fs.readFileSync(JS, 'utf8')) {
  const [i, j] = between(src, DATA_BEGIN, DATA_END);
  const kana = objOf(src.slice(i, j), 'KANA');
  return {
    kana: Object.fromEntries(Object.entries(kana).map(([ch, a]) => [ch, { count: a[0], strokes: a[1].map(([end, len]) => ({ end, len })), ...(a[2] ? { place: a[2] } : {}) }])),
    strokes: JSON.parse(between2(src)), inner: between2(src),
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const data = JSON.parse(fs.readFileSync(path.join(DATA, 'kana.json'), 'utf8'));
  const ofl = JSON.parse(fs.readFileSync(path.join(DATA, 'strokes.ofl.json'), 'utf8'));
  let src = fs.readFileSync(JS, 'utf8');
  const errs = [];
  for (const [a, b, want] of [[DATA_BEGIN, DATA_END, dataBlock(data, ofl)], [OFL_PRE + OFL_MARKERS.begin, OFL_END + ';', stringsBlock(ofl)]]) {
    const [i, j] = between(src, a, b);
    if (check) { if (src.slice(i, j) !== want) errs.push(`the block "${a.slice(14, 40)}…" differs from the data (run node tools/kana-embed.mjs)`); }
    else src = src.slice(0, i) + want + src.slice(j);
  }
  for (const f of LICENSE_FILES) {
    const to = path.join(path.dirname(JS), f), from = fs.readFileSync(path.join(DATA, f));
    if (check) { if (!fs.existsSync(to) || !fs.readFileSync(to).equals(from)) errs.push(`components/kakijun/${f} differs from data/kana/${f}`); }
    else fs.writeFileSync(to, from);
  }
  if (errs.length) { errs.forEach((e) => console.log('FAIL ' + e)); process.exit(1); }
  if (!check) fs.writeFileSync(JS, src);
  console.log(`kana-embed${check ? ' --check' : ''}: ${Object.keys(data.chars).length} characters: ok`);
}
